func ensureCommittedCheckpointWritePolicy(ctx context.Context, repo *git.Repository) error {
	state, err := checkpointpolicy.ReadLocal(ctx, repo)
	if err != nil {
		return fmt.Errorf("read checkpoint policy: %w", err)
